    flower:'M12 12C3 10 4 2 9 4l3 8Zm0 0c-1-9 7-12 8-6l-8 6Zm0 0c9-3 12 5 6 7l-6-7Zm0 0c6 7-1 13-5 8l5-8Zm0 0c-6 7-13 0-8-4l8 4Z',
    chat:'M21 11a9 8 0 0 1-9 8H7l-5 3 2-6a8 8 0 0 1-1-5 9 8 0 0 1 18 0ZM8 10h8M8 14h5',
